import asyncio
import json
from typing import Any
import httpx
from fastmcp import Server

openapi_spec = {
    "openapi": "3.0.0",
    "info": {"title": "Sample API", "version": "1.0.0"},
    "servers": [{"url": "https://api.example.com"}],
    "paths": {
        "/users/{user_id}": {
            "get": {
                "operationId": "getUser",
                "parameters": [
                    {"name": "user_id", "in": "path", "required": True, "schema": {"type": "string"}}
                ],
                "responses": {"200": {"description": "User found"}}
            }
        },
        "/users": {
            "post": {
                "operationId": "createUser",
                "requestBody": {
                    "required": True,
                    "content": {
                        "application/json": {
                            "schema": {
                                "type": "object",
                                "properties": {"name": {"type": "string"}, "email": {"type": "string"}},
                                "required": ["name"]
                            }
                        }
                    }
                },
                "responses": {"201": {"description": "User created"}}
            }
        },
        "/users/{user_id}": {
            "delete": {
                "operationId": "deleteUser",
                "parameters": [
                    {"name": "user_id", "in": "path", "required": True, "schema": {"type": "string"}}
                ],
                "responses": {"204": {"description": "User deleted"}}
            }
        }
    }
}

def generate_mcp_server(spec: dict, client: httpx.AsyncClient) -> Server:
    """Generate an MCP server from OpenAPI 3.0 specification."""
    server = Server("openapi-mcp")

    for path, methods in spec.get("paths", {}).items():
        for method, operation in methods.items():
            if method.lower() not in ["get", "post", "put", "delete", "patch"]:
                continue

            operation_id = operation.get("operationId", f"{method}_{path}")
            description = operation.get("description", f"{method.upper()} {path}")
            parameters = operation.get("parameters", [])
            request_body = operation.get("requestBody")

            properties = {}
            required = []

            for param in parameters:
                param_name = param.get("name")
                properties[param_name] = param.get("schema", {"type": "string"})
                if param.get("required"):
                    required.append(param_name)

            if request_body:
                body_schema = request_body.get("content", {}).get("application/json", {}).get("schema", {})
                if body_schema.get("type") == "object":
                    properties.update(body_schema.get("properties", {}))
                    required.extend(body_schema.get("required", []))

            input_schema = {
                "type": "object",
                "properties": properties,
                "required": list(set(required))
            }

            def create_handler(op_method: str, op_path: str, op_params: list):
                async def handler(**kwargs) -> str:
                    url = op_path

                    for param in op_params:
                        if param.get("in") == "path" and param.get("name") in kwargs:
                            param_name = param.get("name")
                            url = url.replace(f"{{{param_name}}}", str(kwargs.pop(param_name)))

                    try:
                        if op_method.lower() == "get":
                            resp = await client.get(url, params=kwargs)
                        elif op_method.lower() == "post":
                            resp = await client.post(url, json=kwargs)
                        elif op_method.lower() == "put":
                            resp = await client.put(url, json=kwargs)
                        elif op_method.lower() == "delete":
                            resp = await client.delete(url)
                        elif op_method.lower() == "patch":
                            resp = await client.patch(url, json=kwargs)

                        resp.raise_for_status()
                        return json.dumps(resp.json())
                    except httpx.HTTPError as e:
                        return json.dumps({"error": str(e)})

                return handler

            server.add_tool(
                create_handler(method, path, parameters),
                name=operation_id,
                description=description,
                inputSchema=input_schema
            )

    return server

async def main():
    async with httpx.AsyncClient(base_url="https://api.example.com") as client:
        server = generate_mcp_server(openapi_spec, client)
        tools = server.list_tools()
        print(f"Generated {len(tools)} tools from OpenAPI spec:")
        for tool in tools:
            print(f"  - {tool.name}: {tool.description}")

if __name__ == "__main__":
    asyncio.run(main())

